import{D as e,f as t,j as n,m as r,s as i,u as a}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as o}from"./app-ETULAfbl.js";var s=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/Redis/05_%E9%9B%86%E7%BE%A4%E4%B8%8E%E5%88%86%E7%89%87/01_RedisCluster%E5%8E%9F%E7%90%86.html","title":"01 · Redis Cluster 原理","lang":"zh-CN","frontmatter":{"title":"01 · Redis Cluster 原理","icon":"fa6-solid:network-wired","order":1,"category":["Redis"],"tag":["Cluster","哈希槽","Gossip","分布式","故障转移"]},"git":{"createdTime":1780586585000,"updatedTime":1780586585000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":21.11,"words":6332},"filePathRelative":"后端开发/Redis/05_集群与分片/01_RedisCluster原理.md"}`),c={name:`01_RedisCluster原理.md`};function l(o,s,c,l,u,d){let f=n(`Mermaid`);return e(),a(`div`,null,[s[0]||=t(`<h1 id="_01-·-redis-cluster-原理" tabindex="-1"><a class="header-anchor" href="#_01-·-redis-cluster-原理"><span>01 · Redis Cluster 原理</span></a></h1><blockquote><p><strong>本篇回答：</strong> Redis Cluster 是如何用 16384 个哈希槽实现数据分片的？节点之间如何通过 Gossip 协议保持信息同步？当集群发生故障时，自动转移的完整流程是什么？</p></blockquote><hr><h2 id="一、为什么需要-redis-cluster" tabindex="-1"><a class="header-anchor" href="#一、为什么需要-redis-cluster"><span>一、为什么需要 Redis Cluster</span></a></h2><h3 id="_1-1-单机的三重瓶颈" tabindex="-1"><a class="header-anchor" href="#_1-1-单机的三重瓶颈"><span>1.1 单机的三重瓶颈</span></a></h3>`,5),r(f,{code:``}),s[1]||=t(`<table><thead><tr><th>维度</th><th>单机 / 主从</th><th>Sentinel</th><th>Cluster</th></tr></thead><tbody><tr><td>数据容量</td><td>受单机内存限制</td><td>受单机内存限制</td><td>可水平扩展</td></tr><tr><td>读写 QPS</td><td>单主写入瓶颈</td><td>单主写入瓶颈</td><td>多主并行写入</td></tr><tr><td>故障恢复</td><td>手动切换</td><td>自动切换</td><td>自动切换 + 槽迁移</td></tr><tr><td>在线扩容</td><td>不支持</td><td>不支持</td><td>支持（热迁移）</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">重要</p><p>Redis Cluster 不是&quot;万能药&quot;，它用<strong>限制</strong>换取了<strong>扩展性</strong>——跨槽的多键操作受限、事务受限、Select 数据库只能用 DB0。理解这些限制，才能在架构决策中做出正确取舍。</p></div><h3 id="_1-2-cluster-的设计目标" tabindex="-1"><a class="header-anchor" href="#_1-2-cluster-的设计目标"><span>1.2 Cluster 的设计目标</span></a></h3><ul><li><strong>高性能</strong>：客户端直连节点，无代理层开销</li><li><strong>高可用</strong>：主从自动故障转移，无需外部 Sentinel</li><li><strong>可扩展</strong>：支持在线扩容 / 缩容，数据自动迁移</li><li><strong>去中心化</strong>：无中心节点，Gossip 协议自组织</li></ul><hr><h2 id="二、16384-哈希槽——数据分片的核心" tabindex="-1"><a class="header-anchor" href="#二、16384-哈希槽——数据分片的核心"><span>二、16384 哈希槽——数据分片的核心</span></a></h2><h3 id="_2-1-哈希槽映射算法" tabindex="-1"><a class="header-anchor" href="#_2-1-哈希槽映射算法"><span>2.1 哈希槽映射算法</span></a></h3><p>Redis Cluster 将整个键空间划分为 <strong>16384 个哈希槽（Hash Slot）</strong>，每个键通过以下算法确定所属槽：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>slot = CRC16(key) % 16384</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,9),r(f,{code:``}),s[2]||=t(`<div class="hint-container tip"><p class="hint-container-title">CRC16-CCITT</p><p>Redis 使用的 CRC16 是 <strong>CRC-CCITT</strong> 标准（多项式 <code>x^16 + x^12 + x^5 + 1</code>，0x1021），它能产生 0 ~ 65535 的值。取模 16384 后，槽号范围是 <code>0 ~ 16383</code>。</p></div><h3 id="_2-2-为什么是-16384-而不是-65536" tabindex="-1"><a class="header-anchor" href="#_2-2-为什么是-16384-而不是-65536"><span>2.2 为什么是 16384 而不是 65536</span></a></h3><p>这是 Redis 作者 antirez 在 GitHub Issue 中亲自回答的经典问题：</p><table><thead><tr><th>候选槽数</th><th>心跳包大小</th><th>节点密度</th><th>灵敏度</th></tr></thead><tbody><tr><td>65536</td><td>每节点 8KB 心跳</td><td>最多支持 65536 节点</td><td>高</td></tr><tr><td><strong>16384</strong></td><td>每节点 2KB 心跳</td><td>实际够用（&lt;1000 节点）</td><td>合理</td></tr><tr><td>4096</td><td>每节点 512B 心跳</td><td>每主节点平均 2~4 槽</td><td>太粗，迁移不灵活</td></tr></tbody></table><p>选择 16384 的三个理由：</p><ol><li><strong>心跳压缩</strong>：每个节点发送 Gossip 消息时携带自己的槽位图（bitmap），16384 个槽 = 16384 bit = 2KB。如果用 65536 则需要 8KB，在节点数多时浪费带宽</li><li><strong>实用性</strong>：Redis Cluster 建议最大节点数不超过 1000，16384 个槽足够每主节点分配约 16 个槽</li><li><strong>槽迁移粒度</strong>：16384 提供了足够细粒度的迁移单位，4096 则太粗</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>Redis Cluster 官方建议主节点数不超过 1000，实际生产中大多在 3~30 个主节点之间。</p></div><h3 id="_2-3-哈希槽的分布示例" tabindex="-1"><a class="header-anchor" href="#_2-3-哈希槽的分布示例"><span>2.3 哈希槽的分布示例</span></a></h3><p>3 主节点的典型分配：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Node A: slot 0 ~ 5460      (5461 个槽)</span></span>
<span class="line"><span>Node B: slot 5461 ~ 10922   (5462 个槽)</span></span>
<span class="line"><span>Node C: slot 10923 ~ 16383  (5461 个槽)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>6 主节点的典型分配：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Node A: slot 0 ~ 2730</span></span>
<span class="line"><span>Node B: slot 2731 ~ 5461</span></span>
<span class="line"><span>Node C: slot 5462 ~ 8192</span></span>
<span class="line"><span>Node D: slot 8193 ~ 10923</span></span>
<span class="line"><span>Node E: slot 10924 ~ 13654</span></span>
<span class="line"><span>Node F: slot 13655 ~ 16383</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,12),r(f,{code:``}),s[3]||=t(`<h3 id="_2-4-hash-tag——让相关键落在同一个槽" tabindex="-1"><a class="header-anchor" href="#_2-4-hash-tag——让相关键落在同一个槽"><span>2.4 Hash Tag——让相关键落在同一个槽</span></a></h3><p>当需要多个键在同一个槽时（如事务、MGET），使用 <strong>Hash Tag</strong>：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>语法：{...}  只有花括号内的内容参与哈希计算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>key                  → CRC16(&quot;key&quot;) % 16384           = slot 5542</span></span>
<span class="line"><span>{user}:1001:name     → CRC16(&quot;user&quot;) % 16384         = slot 5474</span></span>
<span class="line"><span>{user}:1001:age      → CRC16(&quot;user&quot;) % 16384         = slot 5474</span></span>
<span class="line"><span>{user}:1001:profile  → CRC16(&quot;user&quot;) % 16384         = slot 5474</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 Hash Tag 确保多键在同一节点</span></span>
<span class="line"><span style="color:#61AFEF;">MGET</span><span style="color:#98C379;"> {user}:1001:name</span><span style="color:#98C379;"> {user}:1001:age</span><span style="color:#98C379;"> {user}:1001:profile</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 都在 slot 5474，可以正常执行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 不使用 Hash Tag，跨槽操作会报错</span></span>
<span class="line"><span style="color:#61AFEF;">MGET</span><span style="color:#98C379;"> user:1001:name</span><span style="color:#98C379;"> order:1001:detail</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ CROSSSLOT Keys in request don&#39;t hash to the same slot</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p>Hash Tag 是一把双刃剑：它解决了跨槽问题，但可能导致数据倾斜——如果 Hash Tag 选择不当（如用 <code>{user}</code> 作为所有用户数据的 tag），大量数据会集中在同一个节点，失去分片意义。</p></div><hr><h2 id="三、gossip-协议——节点间信息传播" tabindex="-1"><a class="header-anchor" href="#三、gossip-协议——节点间信息传播"><span>三、Gossip 协议——节点间信息传播</span></a></h2><h3 id="_3-1-gossip-协议概述" tabindex="-1"><a class="header-anchor" href="#_3-1-gossip-协议概述"><span>3.1 Gossip 协议概述</span></a></h3><p>Redis Cluster 采用 <strong>去中心化</strong> 的 Gossip 协议进行节点间的元数据交换。每个节点定期向少量随机节点发送消息，信息像&quot;传染病&quot;一样逐步传播到整个集群。</p>`,9),r(f,{code:``}),s[4]||=t(`<h3 id="_3-2-gossip-消息类型" tabindex="-1"><a class="header-anchor" href="#_3-2-gossip-消息类型"><span>3.2 Gossip 消息类型</span></a></h3><table><thead><tr><th>消息类型</th><th>方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>MEET</strong></td><td>发送方 → 新节点</td><td>将新节点加入集群（类似&quot;邀请入群&quot;）</td></tr><tr><td><strong>PING</strong></td><td>节点 → 随机节点</td><td>心跳检测 + 携带自身状态</td></tr><tr><td><strong>PONG</strong></td><td>响应方 → 发送方</td><td>回复 PING/MEET，携带自身状态</td></tr><tr><td><strong>FAIL</strong></td><td>广播</td><td>标记某节点为 FAIL（已确认宕机）</td></tr><tr><td><strong>PUBLISH</strong></td><td>广播</td><td>传播 Pub/Sub 消息</td></tr></tbody></table>`,2),r(f,{code:``}),s[5]||=t(`<h3 id="_3-3-gossip-消息结构" tabindex="-1"><a class="header-anchor" href="#_3-3-gossip-消息结构"><span>3.3 Gossip 消息结构</span></a></h3><p>每条 Gossip 消息包含以下部分：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  Gossip 消息头                      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ type: PING / PONG / MEET                          │</span></span>
<span class="line"><span>│ sender: 发送方节点 ID（40 字符十六进制）              │</span></span>
<span class="line"><span>│ myslots: 发送方负责的槽位图（2KB bitmap）             │</span></span>
<span class="line"><span>│ flags: 发送方标志（MASTER / SLAVE / PFAIL）         │</span></span>
<span class="line"><span>│ port / cport: 数据端口 / 集群总线端口               │</span></span>
<span class="line"><span>│ cluster_state: OK / FAIL                          │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                  Gossip 消息体                      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ gossip entries: 随机选取的其他节点信息               │</span></span>
<span class="line"><span>│   - node_id                                       │</span></span>
<span class="line"><span>│   - ping_sent / pong_received                     │</span></span>
<span class="line"><span>│   - flags                                         │</span></span>
<span class="line"><span>│   - ip:port                                       │</span></span>
<span class="line"><span>│   （每次携带约 3~10 个节点的信息）                    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-gossip-工作参数" tabindex="-1"><a class="header-anchor" href="#_3-4-gossip-工作参数"><span>3.4 Gossip 工作参数</span></a></h3><table><thead><tr><th>参数</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>cluster-node-timeout</code></td><td>15000ms</td><td>节点超时时间，超时后标记为 PFAIL</td></tr><tr><td>PING 发送间隔</td><td><code>cluster-node-timeout / 10</code></td><td>每隔 1.5 秒向随机节点发送 PING</td></tr><tr><td>每次携带的 Gossip 条目数</td><td>总节点数的 1/10</td><td>控制消息大小</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">调优建议</p><ul><li><code>cluster-node-timeout</code> 不宜设置过小，否则网络抖动容易误判节点故障</li><li>生产环境建议 15~30 秒，网络不稳定时可适当调大</li><li>Gossip 消息的传播延迟约为 <code>O(log N)</code> 个周期，N 为节点数</li></ul></div><hr><h2 id="四、节点握手与加入集群" tabindex="-1"><a class="header-anchor" href="#四、节点握手与加入集群"><span>四、节点握手与加入集群</span></a></h2><h3 id="_4-1-节点握手流程" tabindex="-1"><a class="header-anchor" href="#_4-1-节点握手流程"><span>4.1 节点握手流程</span></a></h3><p>新节点加入集群需要通过 <strong>MEET</strong> 消息完成握手：</p>`,10),r(f,{code:``}),s[6]||=i(`h3`,{id:`_4-2-节点状态机`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#_4-2-节点状态机`},[i(`span`,null,`4.2 节点状态机`)])],-1),r(f,{code:``}),s[7]||=t(`<table><thead><tr><th>状态</th><th>含义</th><th>谁标记</th></tr></thead><tbody><tr><td><strong>HANDSHAKE</strong></td><td>正在握手</td><td>发起方</td></tr><tr><td><strong>MEET</strong></td><td>已收到 MEET，等待确认</td><td>接收方</td></tr><tr><td><strong>CONNECTED</strong></td><td>正常连接</td><td>—</td></tr><tr><td><strong>PFAIL</strong></td><td>疑似故障（Possibly Fail）</td><td>单个节点标记</td></tr><tr><td><strong>FAIL</strong></td><td>确认故障</td><td>多数主节点确认后标记</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">重要</p><p>PFAIL 和 FAIL 的区别是 Redis Cluster 故障检测的核心：PFAIL 只是单个节点的&quot;怀疑&quot;，FAIL 需要多数主节点达成共识。这避免了网络分区导致的误判。</p></div><hr><h2 id="五、槽迁移——在线数据重分布" tabindex="-1"><a class="header-anchor" href="#五、槽迁移——在线数据重分布"><span>五、槽迁移——在线数据重分布</span></a></h2><h3 id="_5-1-迁移场景" tabindex="-1"><a class="header-anchor" href="#_5-1-迁移场景"><span>5.1 迁移场景</span></a></h3><p>当需要扩容（增加主节点）或缩容（减少主节点）时，必须将哈希槽从源节点迁移到目标节点。Redis Cluster 支持<strong>在线迁移</strong>，不需要停机。</p>`,6),r(f,{code:``}),s[8]||=t(`<h3 id="_5-2-ask-与-moved-重定向" tabindex="-1"><a class="header-anchor" href="#_5-2-ask-与-moved-重定向"><span>5.2 ASK 与 MOVED 重定向</span></a></h3><p>槽迁移期间和迁移完成后，客户端可能访问错误的节点，需要通过重定向找到正确的节点：</p><h4 id="moved-重定向——永久迁移" tabindex="-1"><a class="header-anchor" href="#moved-重定向——永久迁移"><span>MOVED 重定向——永久迁移</span></a></h4><p>当客户端访问的键所在槽<strong>已经完全迁移</strong>到新节点时：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>客户端 → Node A: GET user:1001</span></span>
<span class="line"><span>Node A → 客户端: -MOVED 13270 10.0.0.5:6379</span></span>
<span class="line"><span>客户端 → Node B(10.0.0.5:6379): GET user:1001</span></span>
<span class="line"><span>Node B → 客户端: &quot;张三&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="ask-重定向——迁移中临时" tabindex="-1"><a class="header-anchor" href="#ask-重定向——迁移中临时"><span>ASK 重定向——迁移中临时</span></a></h4><p>当键<strong>正在迁移中</strong>，源节点不再持有该键，但目标节点尚未正式接管该槽时：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>客户端 → Node A: GET user:1001</span></span>
<span class="line"><span>Node A → 客户端: -ASK 13270 10.0.0.5:6379</span></span>
<span class="line"><span>客户端 → Node B(10.0.0.5:6379): ASKING</span></span>
<span class="line"><span>Node B → 客户端: OK（临时允许访问）</span></span>
<span class="line"><span>客户端 → Node B: GET user:1001</span></span>
<span class="line"><span>Node B → 客户端: &quot;张三&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,8),r(f,{code:``}),s[9]||=t(`<h3 id="_5-3-ask-vs-moved-对比" tabindex="-1"><a class="header-anchor" href="#_5-3-ask-vs-moved-对比"><span>5.3 ASK vs MOVED 对比</span></a></h3><table><thead><tr><th>维度</th><th>MOVED</th><th>ASK</th></tr></thead><tbody><tr><td>触发时机</td><td>槽已完全迁移</td><td>槽迁移中，键不在源节点</td></tr><tr><td>语义</td><td>永久重定向</td><td>临时重定向</td></tr><tr><td>客户端行为</td><td>更新槽映射缓存</td><td>不更新缓存，仅本次跟随</td></tr><tr><td>后续请求</td><td>直连新节点</td><td>下次仍可能先问源节点</td></tr><tr><td>源节点状态</td><td>槽已不属于自己</td><td>槽仍标记为 MIGRATING</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">注意</p><p>客户端必须正确处理 ASK 和 MOVED，否则在迁移期间会出现大量请求失败。Smart Client（如 Jedis、StackExchange.Redis）已经内置了重定向逻辑。</p></div><h3 id="_5-4-槽迁移的内部实现" tabindex="-1"><a class="header-anchor" href="#_5-4-槽迁移的内部实现"><span>5.4 槽迁移的内部实现</span></a></h3><p>源节点在迁移槽时，内部维护了两个特殊状态：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 源节点：标记槽正在迁出</span></span>
<span class="line"><span style="color:#61AFEF;">CLUSTER</span><span style="color:#98C379;"> SETSLOT</span><span style="color:#D19A66;"> 13270</span><span style="color:#98C379;"> MIGRATING</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">target_node_i</span><span style="color:#ABB2BF;">d&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 目标节点：标记槽正在迁入</span></span>
<span class="line"><span style="color:#61AFEF;">CLUSTER</span><span style="color:#98C379;"> SETSLOT</span><span style="color:#D19A66;"> 13270</span><span style="color:#98C379;"> IMPORTING</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">source_node_i</span><span style="color:#ABB2BF;">d&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>迁移期间的请求处理逻辑：</p>`,7),r(f,{code:``}),s[10]||=i(`hr`,null,null,-1),s[11]||=i(`h2`,{id:`六、故障检测与自动转移`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#六、故障检测与自动转移`},[i(`span`,null,`六、故障检测与自动转移`)])],-1),s[12]||=i(`h3`,{id:`_6-1-故障检测机制`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#_6-1-故障检测机制`},[i(`span`,null,`6.1 故障检测机制`)])],-1),s[13]||=i(`p`,null,`Redis Cluster 的故障检测分为三层：`,-1),r(f,{code:``}),s[14]||=t(`<h3 id="_6-2-pfail-→-fail-的升级条件" tabindex="-1"><a class="header-anchor" href="#_6-2-pfail-→-fail-的升级条件"><span>6.2 PFAIL → FAIL 的升级条件</span></a></h3><p>一个节点被标记为 FAIL 需要满足以下条件：</p><ol><li>至少一个节点标记该节点为 PFAIL</li><li>在 <code>cluster-node-timeout</code> 时间内，<strong>超过半数的主节点</strong>也标记该节点为 PFAIL</li><li>由第一个标记 PFAIL 的节点发起 FAIL 广播</li></ol><div class="hint-container important"><p class="hint-container-title">重要</p><p><strong>只有主节点</strong>的 PFAIL 投票才计数。从节点的 PFAIL 标记不会参与 FAIL 的判定。这是为了保证&quot;多数派&quot;的基数是确定的（主节点数量）。</p></div><h3 id="_6-3-从节点选举与晋升" tabindex="-1"><a class="header-anchor" href="#_6-3-从节点选举与晋升"><span>6.3 从节点选举与晋升</span></a></h3><p>当主节点被标记为 FAIL 后，其从节点将发起选举：</p>`,6),r(f,{code:``}),s[15]||=t(`<h3 id="_6-4-选举规则详解" tabindex="-1"><a class="header-anchor" href="#_6-4-选举规则详解"><span>6.4 选举规则详解</span></a></h3><p>从节点发起选举需要满足以下条件：</p><table><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>主节点被标记 FAIL</td><td>前提条件</td></tr><tr><td>从节点复制偏移量最大</td><td>数据最新的从节点优先</td></tr><tr><td>获得<strong>多数主节点</strong>投票</td><td>超过 N/2 + 1 票</td></tr></tbody></table><p><strong>选举延迟策略</strong>——确保数据最完整的从节点优先选举：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>delay = 500ms + random(0~500ms) + replication_rank * 1000ms</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>replication_rank</code>：从节点的排名，基于复制偏移量</li><li>偏移量最大的从节点 rank=0，延迟最小（500~1000ms）</li><li>偏移量次大的从节点 rank=1，延迟 1500~2000ms</li><li>以此类推</li></ul><div class="hint-container tip"><p class="hint-container-title">提示</p><p>这个延迟策略类似于 Raft 的随机超时机制，既保证了数据最新的从节点优先当选，又避免了多个从节点同时发起选举导致分票。</p></div><h3 id="_6-5-故障转移完整流程" tabindex="-1"><a class="header-anchor" href="#_6-5-故障转移完整流程"><span>6.5 故障转移完整流程</span></a></h3>`,8),r(f,{code:``}),s[16]||=t(`<h3 id="_6-6-故障转移时间估算" tabindex="-1"><a class="header-anchor" href="#_6-6-故障转移时间估算"><span>6.6 故障转移时间估算</span></a></h3><table><thead><tr><th>阶段</th><th>耗时</th><th>说明</th></tr></thead><tbody><tr><td>PFAIL 检测</td><td><code>cluster-node-timeout</code></td><td>默认 15 秒</td></tr><tr><td>FAIL 确认</td><td>1~2 个 Gossip 周期</td><td>约 2~5 秒</td></tr><tr><td>从节点选举</td><td>0.5~2 秒</td><td>延迟策略</td></tr><tr><td>晋升与广播</td><td>&lt; 1 秒</td><td>本地操作</td></tr><tr><td><strong>总计</strong></td><td><strong>约 15~25 秒</strong></td><td>—</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>如果 <code>cluster-node-timeout</code> 设置为 5 秒，故障转移可在约 6~10 秒内完成，但会增加网络抖动时的误判概率。需要根据网络质量权衡。</p></div><hr><h2 id="七、集群拓扑与总线" tabindex="-1"><a class="header-anchor" href="#七、集群拓扑与总线"><span>七、集群拓扑与总线</span></a></h2><h3 id="_7-1-集群总线-cluster-bus" tabindex="-1"><a class="header-anchor" href="#_7-1-集群总线-cluster-bus"><span>7.1 集群总线（Cluster Bus）</span></a></h3><p>每个 Redis Cluster 节点开放两个端口：</p><table><thead><tr><th>端口</th><th>用途</th><th>协议</th></tr></thead><tbody><tr><td><strong>6379</strong></td><td>客户端连接（数据端口）</td><td>Redis Protocol</td></tr><tr><td><strong>16379</strong></td><td>集群总线（节点间通信）</td><td>二进制 Gossip 协议</td></tr></tbody></table><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Node A                             │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  :6379 ◄──── 客户端连接（读写数据）                     │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  :16379 ◄─── 集群总线（PING/PONG/MEET/FAIL）          │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p>防火墙必须同时放行数据端口和集群总线端口。集群总线端口 = 数据端口 + 10000。如果数据端口是 6379，总线端口就是 16379。</p></div><h3 id="_7-2-集群配置文件" tabindex="-1"><a class="header-anchor" href="#_7-2-集群配置文件"><span>7.2 集群配置文件</span></a></h3><p>每个节点维护一个 <code>cluster-config-file</code>（通常命名为 <code>nodes-6379.conf</code>），它记录了集群的完整状态：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># nodes-6379.conf 示例</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 格式：&lt;node_id&gt; &lt;ip:port@cport&gt; &lt;flags&gt; &lt;master_id&gt; &lt;ping_sent&gt; &lt;pong_recv&gt; &lt;config_epoch&gt; &lt;link_state&gt; &lt;slot&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 主节点 A</span></span>
<span class="line"><span style="color:#61AFEF;">a1b2c3d4e5f6...</span><span style="color:#98C379;"> 10.0.0.1:6379@16379</span><span style="color:#98C379;"> myself,master</span><span style="color:#98C379;"> -</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000000</span><span style="color:#D19A66;"> 1</span><span style="color:#98C379;"> connected</span><span style="color:#98C379;"> 0-5460</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 主节点 B</span></span>
<span class="line"><span style="color:#61AFEF;">b2c3d4e5f6a1...</span><span style="color:#98C379;"> 10.0.0.2:6379@16379</span><span style="color:#98C379;"> master</span><span style="color:#98C379;"> -</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000001</span><span style="color:#D19A66;"> 2</span><span style="color:#98C379;"> connected</span><span style="color:#98C379;"> 5461-10922</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 主节点 C</span></span>
<span class="line"><span style="color:#61AFEF;">c3d4e5f6a1b2...</span><span style="color:#98C379;"> 10.0.0.3:6379@16379</span><span style="color:#98C379;"> master</span><span style="color:#98C379;"> -</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000002</span><span style="color:#D19A66;"> 3</span><span style="color:#98C379;"> connected</span><span style="color:#98C379;"> 10923-16383</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从节点 A1（A 的从节点）</span></span>
<span class="line"><span style="color:#61AFEF;">d4e5f6a1b2c3...</span><span style="color:#98C379;"> 10.0.0.4:6379@16379</span><span style="color:#98C379;"> slave</span><span style="color:#98C379;"> a1b2c3d4e5f6...</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000003</span><span style="color:#D19A66;"> 4</span><span style="color:#98C379;"> connected</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从节点 B1（B 的从节点）</span></span>
<span class="line"><span style="color:#61AFEF;">e5f6a1b2c3d4...</span><span style="color:#98C379;"> 10.0.0.5:6379@16379</span><span style="color:#98C379;"> slave</span><span style="color:#98C379;"> b2c3d4e5f6a1...</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000004</span><span style="color:#D19A66;"> 5</span><span style="color:#98C379;"> connected</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从节点 C1（C 的从节点）</span></span>
<span class="line"><span style="color:#61AFEF;">f6a1b2c3d4e5...</span><span style="color:#98C379;"> 10.0.0.6:6379@16379</span><span style="color:#98C379;"> slave</span><span style="color:#98C379;"> c3d4e5f6a1b2...</span><span style="color:#D19A66;"> 0</span><span style="color:#D19A66;"> 1699000005</span><span style="color:#D19A66;"> 6</span><span style="color:#98C379;"> connected</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 变量声明</span></span>
<span class="line"><span style="color:#61AFEF;">vars</span><span style="color:#98C379;"> currentEpoch</span><span style="color:#D19A66;"> 6</span><span style="color:#98C379;"> vars</span><span style="color:#98C379;"> lastVoteEpoch</span><span style="color:#D19A66;"> 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-config-epoch——配置版本号" tabindex="-1"><a class="header-anchor" href="#_7-3-config-epoch——配置版本号"><span>7.3 Config Epoch——配置版本号</span></a></h3><p>Config Epoch 是集群中非常重要的版本控制机制：</p>`,15),r(f,{code:`eJxLy8kvT85ILCpR8AniUgACx2ilF11Nz5t2Pu1a8LR1qU1Skb5dakF+coaCrYKhUqyCrq6dglO00rPle1/sb3y+fDeKAiOlWLAhTmBlzkBlU1tfzprzYu8adJXGUJXOYJUuQJWd3U+7VuBUbwJUD9ZQXFKZk6rgqJCWmZNjpWyUYpJolqSTnJ+TX2SlnJaWhqTGCarGIsnM0tAEuxpnuBoDIMCuxgWqxjDRxNzYEFkNAO3rbfw=`}),s[17]||=t(`<table><thead><tr><th>场景</th><th>Epoch 变化</th></tr></thead><tbody><tr><td>创建集群</td><td>每个主节点分配递增的 epoch</td></tr><tr><td>故障转移</td><td>新主节点自增 epoch</td></tr><tr><td>槽迁移</td><td>迁移完成后目标节点自增 epoch</td></tr><tr><td>手动故障转移</td><td>新主节点自增 epoch</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">重要</p><p>Epoch 解决的核心问题是<strong>冲突解决</strong>：当两个节点对同一个槽的归属有不同看法时，epoch 更大的那个赢。这保证了在网络分区等极端情况下，集群最终能达成一致。</p></div><hr><h2 id="八、集群限制与注意事项" tabindex="-1"><a class="header-anchor" href="#八、集群限制与注意事项"><span>八、集群限制与注意事项</span></a></h2><h3 id="_8-1-跨槽操作限制" tabindex="-1"><a class="header-anchor" href="#_8-1-跨槽操作限制"><span>8.1 跨槽操作限制</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 跨槽 MGET 会报错</span></span>
<span class="line"><span style="color:#61AFEF;">MGET</span><span style="color:#98C379;"> user:1</span><span style="color:#98C379;"> name</span><span style="color:#98C379;"> order:1</span><span style="color:#98C379;"> detail</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># CROSSSLOT Keys in request don&#39;t hash to the same slot</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 使用 Hash Tag 解决</span></span>
<span class="line"><span style="color:#61AFEF;">MGET</span><span style="color:#98C379;"> {user}:1:name</span><span style="color:#98C379;"> {user}:1:detail</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 跨槽事务</span></span>
<span class="line"><span style="color:#61AFEF;">MULTI</span></span>
<span class="line"><span style="color:#61AFEF;">SET</span><span style="color:#98C379;"> user:1:name</span><span style="color:#98C379;"> &quot;张三&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">SET</span><span style="color:#98C379;"> order:1:status</span><span style="color:#98C379;"> &quot;paid&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">EXEC</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># CROSSSLOT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 使用 Hash Tag</span></span>
<span class="line"><span style="color:#61AFEF;">MULTI</span></span>
<span class="line"><span style="color:#61AFEF;">SET</span><span style="color:#98C379;"> {user}:1:name</span><span style="color:#98C379;"> &quot;张三&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">SET</span><span style="color:#98C379;"> {user}:1:status</span><span style="color:#98C379;"> &quot;active&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">EXEC</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-2-其他限制" tabindex="-1"><a class="header-anchor" href="#_8-2-其他限制"><span>8.2 其他限制</span></a></h3><table><thead><tr><th>限制</th><th>说明</th><th>解决方案</th></tr></thead><tbody><tr><td>只能使用 DB0</td><td><code>SELECT</code> 命令不可用</td><td>使用 key 前缀区分命名空间</td></tr><tr><td>跨槽 MGET/MSET</td><td>不支持跨槽批量操作</td><td>使用 Hash Tag 或 Pipeline</td></tr><tr><td>跨槽事务</td><td><code>MULTI/EXEC</code> 中的键必须同槽</td><td>Hash Tag</td></tr><tr><td>跨槽 Lua 脚本</td><td>脚本中访问的所有键必须同槽</td><td>Hash Tag + KEYS 参数</td></tr><tr><td><code>KEYS *</code></td><td>只返回本节点的键</td><td>使用 <code>SCAN</code> 遍历所有节点</td></tr><tr><td><code>FLUSHALL</code></td><td>只清空本节点</td><td>逐节点执行</td></tr><tr><td>集群模式下 Pub/Sub</td><td><code>PUBLISH</code> 会广播到所有节点</td><td>Redis 7.0+ Sharded Pub/Sub</td></tr></tbody></table><h3 id="_8-3-集群规模建议" tabindex="-1"><a class="header-anchor" href="#_8-3-集群规模建议"><span>8.3 集群规模建议</span></a></h3>`,9),r(f,{code:``}),s[18]||=t(`<div class="hint-container warning"><p class="hint-container-title">注意</p><p>Redis Cluster 不建议超过 1000 个主节点。当节点数过多时，Gossip 协议的心跳开销会显著增加，节点间状态同步变慢，故障检测延迟增大。实际上，大多数生产集群在 3~30 个主节点之间。</p></div><hr><h2 id="九、集群数据一致性" tabindex="-1"><a class="header-anchor" href="#九、集群数据一致性"><span>九、集群数据一致性</span></a></h2><h3 id="_9-1-最终一致性" tabindex="-1"><a class="header-anchor" href="#_9-1-最终一致性"><span>9.1 最终一致性</span></a></h3><p>Redis Cluster 采用<strong>异步复制</strong>，主节点写入成功后立即返回客户端，数据异步同步到从节点：</p>`,5),r(f,{code:``}),s[19]||=t(`<h3 id="_9-2-wait-命令——弱同步" tabindex="-1"><a class="header-anchor" href="#_9-2-wait-命令——弱同步"><span>9.2 WAIT 命令——弱同步</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 等待至少 2 个从节点确认复制</span></span>
<span class="line"><span style="color:#61AFEF;">SET</span><span style="color:#98C379;"> key</span><span style="color:#98C379;"> value</span></span>
<span class="line"><span style="color:#61AFEF;">WAIT</span><span style="color:#D19A66;"> 2</span><span style="color:#D19A66;"> 5000</span><span style="color:#7F848E;font-style:italic;">  # 等待 2 个从节点，最多等 5 秒</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 返回值：实际确认的从节点数</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果返回 2，说明数据已同步到 2 个从节点</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p><code>WAIT</code> 不保证强一致性——它只保证在主节点故障时，已确认的从节点拥有数据。但如果是网络分区导致的脑裂，仍可能出现数据不一致。</p></div><h3 id="_9-3-数据丢失场景" tabindex="-1"><a class="header-anchor" href="#_9-3-数据丢失场景"><span>9.3 数据丢失场景</span></a></h3><table><thead><tr><th>场景</th><th>丢失量</th><th>原因</th></tr></thead><tbody><tr><td>主节点宕机，从节点已同步</td><td>0</td><td>正常故障转移</td></tr><tr><td>主节点宕机，从节点落后</td><td>少量（异步复制延迟）</td><td>复制偏移量差异</td></tr><tr><td>网络分区，旧主仍在接受写入</td><td>可能较多</td><td>脑裂场景</td></tr></tbody></table><hr><h2 id="十、集群与-sentinel-的对比" tabindex="-1"><a class="header-anchor" href="#十、集群与-sentinel-的对比"><span>十、集群与 Sentinel 的对比</span></a></h2><table><thead><tr><th>维度</th><th>Redis Cluster</th><th>Sentinel</th></tr></thead><tbody><tr><td>数据分片</td><td>支持（16384 槽）</td><td>不支持</td></tr><tr><td>故障转移</td><td>内置</td><td>独立进程</td></tr><tr><td>扩容</td><td>在线扩容</td><td>不支持</td></tr><tr><td>跨节点操作</td><td>受限（需 Hash Tag）</td><td>不受限</td></tr><tr><td>部署复杂度</td><td>较高（至少 6 节点）</td><td>较低（3~5 Sentinel）</td></tr><tr><td>适用场景</td><td>大数据量 / 高 QPS</td><td>只需高可用，不分片</td></tr></tbody></table>`,8),r(f,{code:`eJxLy8kvT85ILCpRCHHiUgCCwNLU4pLM/LxqpZdzGl4sa3w2dcOz3nVPO9qed7a/3zNfqVZBV9euRunZjPVKNQrOOaXFJalF0UpP9u5/PmWFQlBqSmYxTFQpFsVAiL6nE5YB9QUaVStBDH7Z3q9go/C0d+qzObuetrU+XTsDbAlEpxGyXcGpeSWZeak5cMtgAjB7oKohNkDdwAWWKi6pzElFOCQtMyfHStkoxSTRLEknOT8nv8hKOS0tDUkpVDdUpWGiibmxIXaVMEdAlVokmVkamiArBQAqRIdo`}),s[20]||=t(`<div class="hint-container tip"><p class="hint-container-title">选型建议</p><ul><li>数据量 &lt; 单机内存，只需高可用 → <strong>Sentinel</strong></li><li>数据量 &gt; 单机内存，或 QPS 超过单机 → <strong>Cluster</strong></li><li>已有 Sentinel 架构，数据量增长 → 迁移到 Cluster</li></ul></div><hr><h2 id="十一、关键配置参数一览" tabindex="-1"><a class="header-anchor" href="#十一、关键配置参数一览"><span>十一、关键配置参数一览</span></a></h2><table><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>cluster-enabled</code></td><td>no</td><td>是否开启集群模式</td></tr><tr><td><code>cluster-config-file</code></td><td>nodes.conf</td><td>集群配置文件（自动生成和维护）</td></tr><tr><td><code>cluster-node-timeout</code></td><td>15000ms</td><td>节点超时时间</td></tr><tr><td><code>cluster-announce-ip</code></td><td>&quot;&quot;</td><td>对外宣告的 IP（NAT 环境下使用）</td></tr><tr><td><code>cluster-announce-port</code></td><td>0</td><td>对外宣告的数据端口</td></tr><tr><td><code>cluster-announce-bus-port</code></td><td>0</td><td>对外宣告的总线端口</td></tr><tr><td><code>cluster-require-full-coverage</code></td><td>yes</td><td>是否要求所有槽都有主节点才能服务</td></tr><tr><td><code>cluster-allow-reads-when-down</code></td><td>no</td><td>集群下线时是否允许从节点读</td></tr><tr><td><code>cluster-migration-barrier</code></td><td>1</td><td>从节点迁移屏障</td></tr></tbody></table><h3 id="完整配置示例" tabindex="-1"><a class="header-anchor" href="#完整配置示例"><span>完整配置示例</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># redis.conf — 集群模式配置</span></span>
<span class="line"><span style="color:#61AFEF;">port</span><span style="color:#D19A66;"> 6379</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-enabled</span><span style="color:#98C379;"> yes</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-config-file</span><span style="color:#98C379;"> nodes-6379.conf</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-node-timeout</span><span style="color:#D19A66;"> 15000</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-announce-ip</span><span style="color:#D19A66;"> 10.0.0.1</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-announce-port</span><span style="color:#D19A66;"> 6379</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-announce-bus-port</span><span style="color:#D19A66;"> 16379</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-require-full-coverage</span><span style="color:#98C379;"> yes</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-allow-reads-when-down</span><span style="color:#98C379;"> no</span></span>
<span class="line"><span style="color:#61AFEF;">cluster-migration-barrier</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 持久化配置</span></span>
<span class="line"><span style="color:#61AFEF;">appendonly</span><span style="color:#98C379;"> yes</span></span>
<span class="line"><span style="color:#61AFEF;">appendfsync</span><span style="color:#98C379;"> everysec</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 内存配置</span></span>
<span class="line"><span style="color:#61AFEF;">maxmemory</span><span style="color:#98C379;"> 4gb</span></span>
<span class="line"><span style="color:#61AFEF;">maxmemory-policy</span><span style="color:#98C379;"> noeviction</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="十二、常见问题排查" tabindex="-1"><a class="header-anchor" href="#十二、常见问题排查"><span>十二、常见问题排查</span></a></h2><h3 id="_12-1-集群状态不是-ok" tabindex="-1"><a class="header-anchor" href="#_12-1-集群状态不是-ok"><span>12.1 集群状态不是 OK</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 检查集群状态</span></span>
<span class="line"><span style="color:#61AFEF;">CLUSTER</span><span style="color:#98C379;"> INFO</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cluster_state:fail  ← 不正常</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cluster_state:ok    ← 正常</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查槽覆盖情况</span></span>
<span class="line"><span style="color:#61AFEF;">CLUSTER</span><span style="color:#98C379;"> INFO</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> slots_ok</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># slots_ok:16384     ← 全部槽已分配</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># slots_ok:10922     ← 有槽未分配，集群不可用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常见原因：</p><ul><li>有主节点宕机且无可用从节点</li><li>正在扩容/缩容，槽未完全迁移</li><li><code>cluster-require-full-coverage yes</code>（默认），任何槽无主节点都会导致集群不可用</li></ul><h3 id="_12-2-大量-moved-错误" tabindex="-1"><a class="header-anchor" href="#_12-2-大量-moved-错误"><span>12.2 大量 MOVED 错误</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看客户端统计</span></span>
<span class="line"><span style="color:#61AFEF;">CLUSTER</span><span style="color:#98C379;"> INFO</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> move</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>可能原因：</p><ul><li>刚完成槽迁移，客户端缓存未更新</li><li>网络分区导致部分节点视图不一致</li></ul><p>解决方案：</p><ul><li>使用 Smart Client，自动处理重定向</li><li>确保客户端定期刷新槽映射</li></ul><h3 id="_12-3-节点无法加入集群" tabindex="-1"><a class="header-anchor" href="#_12-3-节点无法加入集群"><span>12.3 节点无法加入集群</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 确认节点配置</span></span>
<span class="line"><span style="color:#61AFEF;">CONFIG</span><span style="color:#98C379;"> GET</span><span style="color:#98C379;"> cluster-enabled</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1) &quot;cluster-enabled&quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2) &quot;yes&quot;    ← 必须为 yes</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查端口连通性</span></span>
<span class="line"><span style="color:#61AFEF;">redis-cli</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> 10.0.0.5</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 6379</span><span style="color:#98C379;"> PING</span></span>
<span class="line"><span style="color:#61AFEF;">redis-cli</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> 10.0.0.5</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 16379</span><span style="color:#98C379;"> PING</span><span style="color:#7F848E;font-style:italic;">  # 总线端口</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="十三、总结" tabindex="-1"><a class="header-anchor" href="#十三、总结"><span>十三、总结</span></a></h2>`,22),r(f,{code:``}),s[21]||=t(`<div class="hint-container important"><p class="hint-container-title">核心要点</p><ol><li><strong>16384 槽</strong>是 Cluster 分片的数学基础，CRC16(key) % 16384 确定键的归属</li><li><strong>Gossip 协议</strong>实现去中心化的状态同步，无需中心节点</li><li><strong>ASK/MOVED</strong> 是迁移期间的两种重定向机制，客户端必须正确处理</li><li><strong>PFAIL → FAIL</strong> 是两阶段故障检测，避免网络抖动误判</li><li><strong>异步复制</strong>意味着 Cluster 不保证强一致性，<code>WAIT</code> 可提供弱同步保障</li></ol></div>`,1)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};